public class Solution {
    public static void main(String[] args) {
        int builderIters = 100_000;

        long startBuilder = System.nanoTime();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < builderIters; i++) {
            sb.append('A');
        }
        long builderDurationMs = (System.nanoTime() - startBuilder) / 1_000_000;

        System.out.println("100,000 appends with StringBuilder completed in: " + builderDurationMs + " ms");
        System.out.println("Performance verdict: StringBuilder provides linear O(N) performance.");
    }
}

public class Solution {
    public static String stripVowels(String input) {
        StringBuilder sb = new StringBuilder(input);
        String vowels = "aeiouAEIOU";

        for (int i = 0; i < sb.length(); i++) {
            if (vowels.indexOf(sb.charAt(i)) != -1) {
                sb.deleteCharAt(i);
                i--; // Adjust index following leftward shift
            }
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        String original = "Java Developer Community";
        String noVowels = stripVowels(original);
        System.out.println("Original:  " + original);
        System.out.println("No Vowels: " + noVowels);
    }
}

public class Solution {
    public static String urlEncodeSpaces(String url) {
        StringBuilder sb = new StringBuilder(url);
        for (int i = 0; i < sb.length(); i++) {
            if (sb.charAt(i) == ' ') {
                sb.replace(i, i + 1, "%20");
                i += 2; // Advance past the 3-character replacement
            }
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        String rawQuery = "search java backend engineering";
        String encoded = urlEncodeSpaces(rawQuery);
        System.out.println("Raw URL:     " + rawQuery);
        System.out.println("Encoded URL: " + encoded);
    }
}

