public class Solution {
    public static String addLargeNumbers(String s1, String s2) {
        StringBuilder sb = new StringBuilder();
        int i = s1.length() - 1;
        int j = s2.length() - 1;
        int carry = 0;

        while (i >= 0 || j >= 0 || carry > 0) {
            int d1 = (i >= 0) ? s1.charAt(i--) - '0' : 0;
            int d2 = (j >= 0) ? s2.charAt(j--) - '0' : 0;
            int sum = d1 + d2 + carry;
            sb.append(sum % 10);
            carry = sum / 10;
        }
        return sb.reverse().toString();
    }

    public static void main(String[] args) {
        String n1 = "99999999999999999999";
        String n2 = "1";
        System.out.println("Sum: " + addLargeNumbers(n1, n2));
    }
}

public class Solution {
    public static String addBinary(String b1, String b2) {
        StringBuilder sb = new StringBuilder();
        int i = b1.length() - 1;
        int j = b2.length() - 1;
        int carry = 0;

        while (i >= 0 || j >= 0 || carry > 0) {
            int bit1 = (i >= 0) ? b1.charAt(i--) - '0' : 0;
            int bit2 = (j >= 0) ? b2.charAt(j--) - '0' : 0;
            int total = bit1 + bit2 + carry;
            sb.append(total % 2);
            carry = total / 2;
        }
        return sb.reverse().toString();
    }

    public static void main(String[] args) {
        String a = "1011"; // 11
        String b = "1101"; // 13
        System.out.println("Binary Sum: " + addBinary(a, b));
    }
}

public class Solution {
    public static String compressRLE(String text) {
        if (text == null || text.length() <= 2) return text;
        StringBuilder sb = new StringBuilder(text.length());
        int count = 1;

        for (int i = 1; i < text.length(); i++) {
            if (text.charAt(i) == text.charAt(i - 1)) {
                count++;
            } else {
                sb.append(text.charAt(i - 1)).append(count);
                count = 1;
            }
        }
        sb.append(text.charAt(text.length() - 1)).append(count);
        return sb.length() < text.length() ? sb.toString() : text;
    }

    public static void main(String[] args) {
        String original = "aabcccccaaa";
        System.out.println("Compressed: " + compressRLE(original));
    }
}

public class Solution {
    public static String intToRoman(int num) {
        int[] values = {1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1};
        String[] symbols = {"M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"};
        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < values.length && num > 0; i++) {
            while (num >= values[i]) {
                sb.append(symbols[i]);
                num -= values[i];
            }
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        int year = 1994;
        System.out.println("Integer: " + year);
        System.out.println("Roman:   " + intToRoman(year));
    }
}

public class Solution {
    public static String wrapText(String text, int maxWidth) {
        String[] words = text.split("\\s+");
        StringBuilder sb = new StringBuilder();
        int currentLineLen = 0;

        for (String w : words) {
            if (currentLineLen + w.length() + (currentLineLen > 0 ? 1 : 0) > maxWidth) {
                sb.append("\n");
                sb.append(w);
                currentLineLen = w.length();
            } else {
                if (currentLineLen > 0) {
                    sb.append(" ");
                    currentLineLen++;
                }
                sb.append(w);
                currentLineLen += w.length();
            }
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        String sentence = "Java StringBuilder provides an unsynchronized high performance mutable buffer";
        String wrapped = wrapText(sentence, 20);
        System.out.println(wrapped);
    }
}
